-- Edward approved golf catalog and group round-trip fares. Run this file only.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS golf_course_catalog (
 golf_course_id INT UNSIGNED PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE,
 names JSON NOT NULL, fare_group ENUM('A','B','C') NOT NULL,
 coordinate_source VARCHAR(1024) NOT NULL,
 CONSTRAINT fk_golf_catalog_course FOREIGN KEY(golf_course_id) REFERENCES golf_courses(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS golf_group_prices (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, fare_group ENUM('A','B','C') NOT NULL,
 vehicle_code VARCHAR(30) NOT NULL, holes SMALLINT UNSIGNED NOT NULL,
 round_trip_price DECIMAL(12,2) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1,
 UNIQUE KEY uk_golf_group_vehicle_holes(fare_group,vehicle_code,holes)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
